  .limericks-grid { grid-template-columns: 1fr; gap: 2.5rem; }
}

.limerick-card {
  background: var(--bg-card);
  color: var(--text-dark);
  padding: 2.5rem 2rem 4rem;
  position: relative;
  box-shadow:
    0 8px 25px rgba(0,0,0,0.25),
    0 2px 8px rgba(0,0,0,0.15);
  transition:
    transform 700ms var(--ease-emphasis),
    box-shadow 700ms var(--ease-quiet),
    opacity 700ms var(--ease-quiet);
  opacity: 0;
  transform: translateY(40px) rotate(var(--rot, 0deg));
  transform-origin: center center;
  cursor: default;
  will-change: transform;
}
.limerick-card.is-shown {
  opacity: 1;
  transform: translateY(0) rotate(var(--rot, 0deg));
}
.limerick-card:hover {
  transform: translateY(-4px) rotate(0deg) scale(1.025);
  box-shadow:
    0 25px 50px rgba(0,0,0,0.5),
    0 10px 20px rgba(0,0,0,0.25);
  z-index: 5;
}
.limerick-card .stamp {
  position: absolute;
  top: 1.25rem;
  left: 1.5rem;
  font-family: 'Fira Code', monospace;
  font-size: 9px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-soft-dark);
  border: 1px solid var(--text-soft-dark);
  padding: 0.25rem 0.5rem;
  opacity: 0.45;
  transform: rotate(-3deg);
}
.limerick-card .num {
  position: absolute;
  top: 1.4rem;
  right: 1.5rem;
  font-family: 'Fira Code', monospace;
  font-size: 10px;
  letter-spacing: 0.15em;
  color: var(--accent);
  opacity: 0.85;
}
.limerick-card .text {
  font-family: 'EB Garamond', serif;
  font-weight: 400;
  font-size: 1.1rem;
  line-height: 1.7;
  color: var(--text-dark);
  margin-top: 2.75rem;
}
.limerick-card .text .line { display: block; }
.limerick-card .text .line.short {
  padding-left: 1.5rem;
  font-style: italic;
  color: var(--text-soft-dark);
}
.limerick-card .caption {
  position: absolute;
  bottom: 1.25rem;
  left: 50%;
  transform: translateX(-50%) rotate(-1deg);
  font-family: 'Caveat', cursive;
  font-size: 1.15rem;
  color: var(--text-soft-dark);
  white-space: nowrap;
  font-weight: 600;
}

/* ============================================================
   FOOTER
   ============================================================ */
