  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--text-soft-dark);
  opacity: 0;
  transition: opacity 1000ms var(--ease-quiet) 800ms;
  flex-wrap: wrap;
  gap: 1rem;
  max-width: 1400px;
